@@ -1,24 +1,34 @@
 export interface EndpointCandidate {
   id: string;
   kind: 'http' | 'grpc';
 }

 export interface EligibleResult<T extends EndpointCandidate> {
   eligible: true;
   candidate: T;
 }

 export interface IneligibleResult {
   eligible: false;
   reason: string;
 }

 export type EligibilityResult<T extends EndpointCandidate> =
   | EligibleResult<T>
   | IneligibleResult;

-export function evaluateEligibility<T extends EndpointCandidate>(
-  candidate: T,
-  enabledKinds: EndpointCandidate['kind'][]
-): EligibilityResult<T> {
+export function evaluateEligibility<const T extends EndpointCandidate>(
+  candidate: T,
+  enabledKinds: ReadonlyArray<T['kind']>
+): EligibilityResult<T> {
   if (!enabledKinds.includes(candidate.kind)) {
     return {
       eligible: false,
       reason: `Kind ${candidate.kind} is not enabled`,
     };
   }

   return {
     eligible: true,
     candidate,
   };
 }
diff --git a/test/evaluateEligibility.test.ts b/test/evaluateEligibility.test.ts
index 1a2b3c4..5d6e7f8 100644
--- a/test/evaluateEligibility.test.ts
+++ b/test/evaluateEligibility.test.ts
@@ -1,16 +1,44 @@
 import { evaluateEligibility } from '../src/evaluateEligibility';

 describe('evaluateEligibility', () => {
   it('returns eligible candidate when enabled', () => {
-    const candidate = { id: '1', kind: 'http' };
+    const candidate = { id: '1', kind: 'http' } as const;
     const result = evaluateEligibility(candidate, ['http']);

     expect(result.eligible).toBe(true);
     if (result.eligible) {
       expect(result.candidate).toBe(candidate);
     }
   });

   it('returns ineligible when kind is disabled', () => {
-    const candidate = { id: '2', kind: 'grpc' };
+    const candidate = { id: '2', kind: 'grpc' } as const;
     const result = evaluateEligibility(candidate, ['http']);

     expect(result).toEqual({
       eligible: false,
       reason: 'Kind grpc is not enabled',
     });
   });
+
+  it('preserves literal candidate type in the eligible branch', () => {
+    const candidate = {
+      id: '3',
+      kind: 'http',
+      path: '/health',
+    } as const;
+
+    const result = evaluateEligibility(candidate, ['http']);
+
+    if (result.eligible) {
+      const typed: '/health' = result.candidate.path;
+      expect(typed).toBe('/health');
+    }
+  });
+
+  it('rejects enabledKinds values that cannot match the candidate kind at compile time', () => {
+    const candidate = { id: '4', kind: 'grpc' } as const;
+
+    // This assertion verifies the generic inference fix: enabledKinds is now tied
+    // to T["kind"], so a grpc candidate cannot be checked against http-only kinds.
+    // @ts-expect-error http is not assignable to grpc
+    evaluateEligibility(candidate, ['http']);
+
+    expect(true).toBe(true);
+  });
 });

Why this fixes it: using `const T extends EndpointCandidate` preserves the literal candidate shape during inference, and changing `enabledKinds` from `EndpointCandidate['kind'][]` to `ReadonlyArray<T['kind']>` couples the second parameter to the inferred candidate kind instead of widening it to the full union. That prevents incorrect calls like a `grpc` candidate with `['http']` from type-checking and keeps the eligible branch strongly typed to the original candidate literal."
}

